#!/usr/bin/env python3
"""Build the self-contained, dependency-free banana-1 study report."""
from __future__ import annotations
import argparse, json, sys
from pathlib import Path
import numpy as np

ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'scripts'))
from banana1_representation_study import metric, score, bootstrap


def main():
    p=argparse.ArgumentParser();p.add_argument('--study',type=Path,default=ROOT/'reports/banana1_study');a=p.parse_args()
    r=json.loads((a.study/'results.json').read_text());arrays=np.load(a.study/'activations.npz');params=json.loads((a.study/'probe_parameters.json').read_text())
    test=arrays['split']==2;targets=arrays['targets'];group=arrays['group'];split=arrays['split']
    predictions=np.load(a.study/'test_predictions.npz');rng=np.random.default_rng(r['seed'])
    intervention_indices=np.sort(rng.choice(np.flatnonzero(test),size=r['intervention_rows'],replace=False))
    display=dict(r);display.pop('neuron_map');display['scatter']={};display['correlations']={};display['intervention_baseline']={}
    for i,c in enumerate(r['concepts']):
        key=c['key'];layer=c['best_single_layer_selected_on_validation'];j=c['single_neurons'][layer]['neuron']
        ix=np.flatnonzero(test & np.isfinite(targets[:,i]));ix=rng.choice(ix,min(250,len(ix)),replace=False)
        fullpred=predictions[key+'__fused_after_think'];testloc=np.searchsorted(np.flatnonzero(test),ix)
        display['scatter'][key]=dict(layer=layer,neuron=j,points=np.round(np.column_stack([targets[ix,i],arrays[layer][ix,j],fullpred[testloc]]),4).tolist())
        for layer in ['gru_layer0','gru_layer1','global','fused_before_think','fused_after_think']:
            display['correlations'][key+'__'+layer]=np.round(r['neuron_map'][key+'__'+layer]['correlation'],4).tolist()
        par=params[key+'__fused_after_think'];h=arrays['fused_after_think'][intervention_indices];pred=(h-par['mean'])/par['scale']@np.asarray(par['coef'])+par['intercept']
        display['intervention_baseline'][key]=metric(targets[intervention_indices,i],pred,c['kind']=='binary')
        # Paired, whole-battle resampling: compare the trained final state with
        # the mean SCORE of the two random initializations, not their logits.
        y=targets[test,i];pfull=predictions[key+'__fused_after_think'];p1=predictions[key+'__random_seed17'];p2=predictions[key+'__random_seed83']
        gs=group[test];valid=np.isfinite(y);ug=np.unique(gs);indices=[np.flatnonzero((gs==g)&valid) for g in ug];brng=np.random.default_rng(902+i);diff=[]
        for _ in range(300):
            idx=np.concatenate([indices[j] for j in brng.integers(len(ug),size=len(ug))]);binary=c['kind']=='binary'
            diff.append(score(y[idx],pfull[idx],binary)-.5*(score(y[idx],p1[idx],binary)+score(y[idx],p2[idx],binary)))
        name='balanced_accuracy' if c['kind']=='binary' else 'r2'
        c['trained_minus_random_mean']=c['results']['fused_after_think'][name]-.5*(c['results']['random_seed17'][name]+c['results']['random_seed83'][name])
        c['trained_minus_random_ci95']=np.quantile(diff,[.025,.975]).tolist()
    source=Path(r['source_root']);old=json.loads((source/'models/policy_bc_v4.4.2/report.json').read_text());display['original_training']={k:old[k] for k in ['model_name','created_at','seconds','compute','data','history']}
    # Compact evidence for the HTML; full precision lives beside it.
    def compact(x):
        if isinstance(x,float):return round(x,5)
        if isinstance(x,list):return [compact(v) for v in x]
        if isinstance(x,dict):return {k:compact(v) for k,v in x.items()}
        return x
    data=json.dumps(compact(display),separators=(',',':')).replace('</','<\\/')
    html=TEMPLATE.replace('__DATA__',data)
    (a.study/'index.html').write_text(html)
    (a.study/'report_data.json').write_text(json.dumps(display,indent=2))
    print(json.dumps(dict(path=str(a.study/'index.html'),bytes=len(html.encode()),concepts=len(r['concepts']),charts='native SVG, no external dependencies')))


